actions.script:
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
periodStr = fromD + ' to ' + thruD
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def f = ec.entity.find("zenith.erp.pos.PosAmendmentView")
    .condition("amendmentDate", "greater-equals", java.sql.Timestamp.valueOf(fromD + ' 00:00:00'))
    .condition("amendmentDate", "less-equals", java.sql.Timestamp.valueOf(thruD + ' 23:59:59'))
if (_org && _org != '_NA_') f.condition("organizationPartyId", _org)
def ams = f.orderBy("amendmentDate").list()
def ctLabel = { ct -> [PRICE_CHANGE:'Item Price', QTY_CHANGE:'Item Qty', DISCOUNT_CHANGE:'Discount', ITEM_ADDED:'Item Added', ITEM_REMOVED:'Item Removed', TAX_CHANGE:'Tax'].get(ct) ?: (ct ?: '') }
def billMap = new LinkedHashMap()
ams.each { a -> def tid = a.transactionId; def b = billMap[tid]
    if (b == null) { b = [billNo:(a.transactionNumber ?: tid), firstBefore:(a.oldGrandTotal != null ? (a.oldGrandTotal as BigDecimal) : null), lastAfter:null, editsMade:0, lastDate:null, editId:null, editedBy:null, terminal:null, reason:null]; billMap[tid] = b }
    b.editsMade++; if (b.firstBefore == null && a.oldGrandTotal != null) b.firstBefore = a.oldGrandTotal as BigDecimal
    if (a.newGrandTotal != null) b.lastAfter = a.newGrandTotal as BigDecimal
    b.lastDate = a.amendmentDate; b.editId = a.amendmentId
    def nm = "${a.firstName ?: ''} ${a.lastName ?: ''}".toString().trim(); b.editedBy = nm ?: (a.amendedByPartyId ?: '')
    b.terminal = a.terminalName ?: ''; b.reason = (a.reason && a.reason.trim()) ? a.reason.trim() : ctLabel(a.changeType) }
def all = billMap.values().toList().sort { -(it.lastDate ? it.lastDate.getTime() : 0L) }
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) all = all.findAll { [it.billNo, it.editedBy, it.reason, it.terminal].collect { (it ?: '').toString().toLowerCase() }.any { it.contains(stx) } }
rowCountStr = all.size().toString()
def amt = { v -> v == null ? '0.00' : ec.l10n.format((v as BigDecimal), '#,##0.00') }
def dtf = { v -> v == null ? '' : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
rows = all.collect { b -> def d = (b.lastAfter ?: 0G) - (b.firstBefore ?: 0G)
    [eid:x(b.editId), bill:x(b.billNo), dt:x(dtf(b.lastDate)), who:x(b.editedBy), term:x(b.terminal),
     edits:b.editsMade.toString(), bef:amt(b.firstBefore), aft:amt(b.lastAfter),
     diff:((d >= 0G ? '+' : '-') + amt(d.abs())), reason:x(b.reason)] }
